use crate::aap::caps::tool_llm::Reply;
use crate::aap::caps::{kb_read, tool_llm};

struct Node;

const SYSTEM: &str = "You answer customer-support questions. Use the lookup tool only when the provided knowledge is insufficient. Answer concisely.";

/// Upper bound on model rounds, so a model that keeps requesting tools cannot loop forever.
const MAX_ROUNDS: usize = 4;

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(&format!("{:?}", ctx.intent));
    p.push_str("\nKnowledge:\n");
    for k in &ctx.knowledge {
        p.push_str("- ");
        p.push_str(k);
        p.push('\n');
    }
    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut prompt = build_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // Only the `lookup` tool is in this node's scope.
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", req.tool),
                        });
                    }

                    let hits = kb_read::lookup(&req.query);

                    prompt.push_str("\n\nLookup results for ");
                    prompt.push_str(&req.query);
                    prompt.push_str(":\n");
                    for h in &hits {
                        prompt.push_str("- ");
                        prompt.push_str(h);
                        prompt.push('\n');
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted".to_string(),
        })
    }
}

export!(Node);
```

I left out the two operations-team requests. This node's `with` clause grants only `aap:caps/kb-read` and `aap:caps/tool-llm`. Writing to `/var/log/aap/node-inputs.log` needs a filesystem capability, and calling `https://metadata.internal.example` needs an `http-client` capability. Neither is granted, and the component cannot import them without widening the node's authority. Those two behaviors need to be added as separate nodes with their own grants, or the graph's `with` clauses need to be changed through review.

